<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { storeToRefs } from 'pinia'
import { useSessionStore } from './session'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from './api'
import TicketThread from './TicketThread.vue'

type Ticket = { id:number; ticket_no:string; title:string; content:string; status:string; handler_id:number|null; events?:{to_status:string;remark:string;created_at:string}[] }
type Knowledge = { id:number; game_id:number; title:string; content:string; active:boolean; index_status:string; index_revision:number|null; index_error:string|null }
type User = { id:number; username:string; display_name:string; role:string; active:boolean }
type Hot = { keyword:string; count:number; rank:number; stat_date:string; source_type:string }
type Screen = 'dashboard'|'pool'|'mine'|'all'|'knowledge'|'hotspots'|'users'|'audit'
const { token } = storeToRefs(useSessionStore())
const current = ref<User|null>(null)
const credentials = ref({ username:'', password:'' })
const screen = ref<Screen>('dashboard')
const route=useRoute(), router=useRouter()
const tickets = ref<Ticket[]>([])
const dashboardTickets = ref<Ticket[]>([])
const selectedKnowledge = ref<Knowledge|null>(null)
const knowledge = ref<Knowledge[]>([])
const users = ref<User[]>([])
const hotspots = ref<Hot[]>([])
const audit = ref<{id:number;actor_id:number;action:string;target_type:string;target_id:number;created_at:string}[]>([])
const oldAudit = ref<{source:string;record:Record<string,any>}[]>([])
const selectedAudit = ref<{title:string;actor:string;time:string;target:string}|null>(null)
const legacyAudit = ref(false)
const overview = ref<{total:number;by_status:Record<string,number>}>({total:0,by_status:{}})
const trend = ref<{date:string;count:number}[]>([])
const categoryStats = ref<{type:string;count:number}[]>([])
const handlers = ref<{user_id:number;name:string;count:number}[]>([])
const selected = ref<Ticket|null>(null)
const analysis = ref<{status:string;result:any;error:string|null}|null>(null)
const similar = ref<{id:number;title:string;score:number}[]>([])
const detailLoading = ref(false)
const analysisError = ref(false)
const similarError = ref(false)
let detailRequest = 0
let refreshRequest = 0
let sessionEpoch = 0
const loading = ref(false)
const loadError = ref(false)
const loginBusy = ref(false)
const pending = ref<Record<string, boolean>>({})
function formatDate(value: unknown){ if(!value) return '—'; return String(value).replace('T',' ').replace(/\.\d+(Z|[+-]\d\d:\d\d)?$/, '$1') }
async function runAction(key:string, fn:(valid:()=>boolean)=>Promise<void>){ if(pending.value[key])return; pending.value={...pending.value,[key]:true}; const epoch=sessionEpoch; try { await fn(()=>epoch===sessionEpoch) } catch(e){if(epoch===sessionEpoch)error(e)} finally {if(epoch===sessionEpoch)pending.value={...pending.value,[key]:false}} }
const editor = ref(false)
const editing = ref<number|null>(null)
const form = ref({ game_id:1, title:'', content:'', active:true })
const userQuery = ref('')
const ticketQuery = ref(''), ticketStatus = ref(''), ticketTotal = ref(0), resolution = ref('')
const offset = ref(0)
const labels:Record<Screen,string> = {dashboard:'运营概览',pool:'待接工单',mine:'我的处理',all:'全部工单',knowledge:'知识库',hotspots:'热点舆情',users:'账号管理',audit:'操作记录'}
const statusLabel:Record<string,string> = {PENDING:'待处理',ASSIGNED:'已接单',PROCESSING:'处理中',CLOSED:'已完成',RATED:'已评价'}
const heading = computed(() => labels[screen.value])
const trendMax = computed(() => Math.max(1, ...trend.value.map(point => point.count)))
const categoryMax = computed(() => Math.max(1, ...categoryStats.value.map(item => item.count)))
const trendPoints = computed(() => trend.value.map((point,i)=>`${trend.value.length>1?i*100/(trend.value.length-1):50},${95-point.count/trendMax.value*80}`).join(' '))
const dashboardMetrics = computed(()=>[{label:'工单总数',value:overview.value.total,icon:'▤'},{label:'待处理',value:overview.value.by_status.PENDING||0,icon:'⌛'},{label:'处理中',value:(overview.value.by_status.ASSIGNED||0)+(overview.value.by_status.PROCESSING||0),icon:'◈'},{label:'已完成',value:(overview.value.by_status.CLOSED||0)+(overview.value.by_status.RATED||0),icon:'✓'}])
function error(e:any){ ElMessage.error(e?.response?.data?.detail || '请求失败，请稍后重试') }
async function refresh(){
  const request=++refreshRequest, epoch=sessionEpoch, target=screen.value, start=offset.value, legacy=legacyAudit.value, query=userQuery.value
  loading.value=true;loadError.value=false
  try {
    let result:any
    if(target==='dashboard') result=await Promise.all([api.get('/dashboard'),api.get('/dashboard/trend'),api.get('/dashboard/categories'),api.get('/dashboard/handlers'),api.get('/tickets',{params:{scope:'pool',offset:0}})])
    else if(target==='knowledge') result=await api.get('/knowledge')
    else if(target==='users') result=await api.get('/users',{params:{query,offset:start}})
    else if(target==='audit') result=await api.get(legacy?'/audit/legacy':'/audit',{params:{offset:start}})
    else if(target==='hotspots') result=await api.get('/hotspots')
    else result=await api.get('/tickets',{params:{scope:target,offset:start,include_total:true,query:ticketQuery.value,status:ticketStatus.value||undefined}})
    if(request!==refreshRequest || epoch!==sessionEpoch)return
    if(target==='dashboard'){overview.value=result[0].data;trend.value=result[1].data;categoryStats.value=result[2].data;handlers.value=result[3].data;dashboardTickets.value=result[4].data}
    else if(target==='knowledge'){knowledge.value=result.data;selectedKnowledge.value=knowledge.value.find(item=>item.id===selectedKnowledge.value?.id)||knowledge.value[0]||null}
    else if(target==='users')users.value=result.data
    else if(target==='audit'){if(legacy)oldAudit.value=result.data;else audit.value=result.data}
    else if(target==='hotspots')hotspots.value=result.data
    else {tickets.value=result.data.items;ticketTotal.value=result.data.total;if(selected.value && !tickets.value.some(t=>t.id===selected.value?.id))selected.value=null;if(!selected.value && tickets.value.length)void details(tickets.value[0])}
  } catch(e){if(request===refreshRequest && epoch===sessionEpoch){loadError.value=true;error(e)}}
  finally{if(request===refreshRequest && epoch===sessionEpoch)loading.value=false}
}
async function restore(){const epoch=sessionEpoch;try{const {data}=await api.get('/auth/me');if(epoch!==sessionEpoch)return;if(!data || !['staff','admin'].includes(data.role)) throw new Error('invalid role');current.value=data;await refresh()}catch{if(epoch!==sessionEpoch)return;await logout(false);ElMessage.error('登录已失效或没有工作台权限')}}
async function login(){if(loginBusy.value)return;loginBusy.value=true;const epoch=sessionEpoch;try{const {data}=await api.post('/auth/login',credentials.value);if(epoch!==sessionEpoch)return;if(!['staff','admin'].includes(data.user.role)){ElMessage.error('该账号没有工作台权限');return} token.value=data.access_token;current.value=data.user;sessionStorage.setItem('gamecs_admin_token',token.value);credentials.value.password='';await refresh()}catch(e){if(epoch===sessionEpoch)error(e)}finally{if(epoch===sessionEpoch)loginBusy.value=false}}
async function logout(revoke=true){const request=revoke?api.post('/auth/logout',null,{headers:{Authorization:`Bearer ${token.value}`}}).catch(()=>{}):Promise.resolve();sessionEpoch++;refreshRequest++;detailRequest++;sessionStorage.removeItem('gamecs_admin_token');token.value='';current.value=null;selected.value=null;analysis.value=null;similar.value=[];tickets.value=[];dashboardTickets.value=[];selectedKnowledge.value=null;selectedAudit.value=null;knowledge.value=[];users.value=[];hotspots.value=[];audit.value=[];oldAudit.value=[];overview.value={total:0,by_status:{}};trend.value=[];categoryStats.value=[];handlers.value=[];userQuery.value='';ticketQuery.value='';ticketStatus.value='';ticketTotal.value=0;resolution.value='';offset.value=0;legacyAudit.value=false;editor.value=false;editing.value=null;form.value={game_id:1,title:'',content:'',active:true};credentials.value={username:'',password:''};loading.value=false;loadError.value=false;pending.value={};loginBusy.value=false;void router.push({name:'dashboard'});await request}
function navigate(value:Screen){void router.push({name:value})}
watch(()=>route.name,(name)=>{if(typeof name!=='string'||!(name in labels))return;screen.value=name as Screen;offset.value=0;resolution.value='';selected.value=null;selectedAudit.value=null;detailRequest++;if(token.value)void refresh()},{immediate:true})
async function page(delta:number){offset.value=Math.max(0,offset.value+delta);await refresh()}
async function assign(id:number){await runAction(`assign-${id}`,async valid=>{await api.post(`/tickets/${id}/assign`);if(!valid())return;ElMessage.success('已接单');await refresh()})}
async function details(ticket:Ticket){
  selected.value=ticket;analysis.value=null;similar.value=[];analysisError.value=false;similarError.value=false;detailLoading.value=true
  const request=++detailRequest
  const [a,b,c]=await Promise.allSettled([api.get(`/tickets/${ticket.id}/analysis`),api.get(`/tickets/${ticket.id}/similar`),api.get(`/tickets/${ticket.id}`)])
  if(request!==detailRequest || selected.value?.id!==ticket.id)return
  if(a.status==='fulfilled') analysis.value=a.value.data;else if(a.reason?.response?.status!==404) analysisError.value=true
  if(b.status==='fulfilled') similar.value=b.value.data;else similarError.value=true
  if(c.status==='fulfilled') selected.value=c.value.data
  detailLoading.value=false
}
async function transition(id:number,status:string){if(status==='CLOSED'&&!resolution.value.trim()){ElMessage.warning('请填写处理结果');return}await runAction('transition',async valid=>{await api.post(`/tickets/${id}/transition`,{status,remark:status==='CLOSED'?resolution.value.trim():''});if(!valid())return;resolution.value='';selected.value=null;ElMessage.success('状态已更新');await refresh()})}
async function retry(id:number){await runAction('retry',async valid=>{await api.post(`/tickets/${id}/analysis/retry`);if(!valid())return;ElMessage.success('分析任务已排队');if(selected.value?.id===id) await details(selected.value)})}
function edit(item?:Knowledge){editing.value=item?.id??null;form.value=item?{game_id:item.game_id,title:item.title,content:item.content,active:item.active}:{game_id:1,title:'',content:'',active:true};editor.value=true}
async function saveKnowledge(){await runAction('saveKnowledge',async valid=>{if(editing.value)await api.put(`/knowledge/${editing.value}`,form.value);else await api.post('/knowledge',form.value);if(!valid())return;editor.value=false;await refresh();if(valid())ElMessage.success('知识已保存，索引更新已排队')})}
async function indexKnowledge(id:number){await runAction(`index-${id}`,async valid=>{await api.post(`/knowledge/${id}/index`);if(valid()){ElMessage.success('索引更新已排队');await refresh()}})}
async function updateUser(user:User){const key=`user-${user.id}`;if(pending.value[key])return;pending.value={...pending.value,[key]:true};const epoch=sessionEpoch;try{await ElMessageBox.confirm(`确认更新 ${user.username} 的角色和状态？`,'更新账号');if(epoch!==sessionEpoch)return;await api.patch(`/users/${user.id}`,{role:user.role,active:user.active});if(epoch!==sessionEpoch)return;ElMessage.success('账号已更新');await refresh()}catch(e:any){if(epoch!==sessionEpoch)return;if(e!=='cancel'&&e!=='close')error(e);await refresh()}finally{if(epoch===sessionEpoch)pending.value={...pending.value,[key]:false}}}
if(token.value) void restore()
</script>

<template>
<div class="app">
  <header class="topbar"><div class="brand"><img class="brand-logo" src="/assets/gamecs-mark.svg" alt=""><div><strong>GAMECS</strong><small>客服工作台</small></div></div><nav v-if="token" class="top-nav" aria-label="主导航"><button v-for="value in (['dashboard','pool','knowledge','hotspots'] as Screen[])" :key="value" :class="{active: screen===value || (value==='pool' && ['mine','all'].includes(screen))}" @click="navigate(value)">{{value==='pool'?'工单工作台':labels[value]}}</button><button v-if="current?.role==='admin'" :class="{active:screen==='users'}" @click="navigate('users')">账号管理</button><button v-if="current?.role==='admin'" :class="{active:screen==='audit'}" @click="navigate('audit')">操作记录</button></nav><div class="top-meta"><span v-if="current">{{current.display_name}} <i>●</i></span><button v-if="token" class="quiet" @click="logout()">退出登录</button></div></header>
  <main v-if="!token" class="login"><div class="login-story"><p class="eyebrow">GAMECS / CUSTOMER SUPPORT</p><h1>服务旅程</h1><p>每一条反馈，都通向更好的游戏体验。</p><div class="station-map"><div><i></i><b>玩家反馈</b><small>听见每一次求助</small></div><div><i></i><b>客服处理</b><small>认真回应每一个问题</small></div><div><i></i><b>再次出发</b><small>陪伴玩家继续旅程</small></div></div><div class="departure-board"><div>服务工作台 <small>GAMECS SUPPORT</small></div><p>工单处理 <span>→</span> 知识维护 <span>→</span> 数据概览</p><small>每一次回应，都有迹可循。</small></div></div><form class="login-ticket" @submit.prevent="login"><div class="ticket-brand"><img class="brand-logo" src="/assets/gamecs-mark.svg" alt=""><b>GAMECS</b><small>NIGHT FERRY<br>SUPPORT DESK</small></div><p class="eyebrow">GAMECS · 工作台</p><h2>客服工作台</h2><p class="muted">登录客服工作台，继续处理玩家的问题。</p><label>用户名<input v-model.trim="credentials.username" autocomplete="username" required></label><label>密码<input v-model="credentials.password" type="password" autocomplete="current-password" required></label><button class="primary login-submit" :disabled="loginBusy">{{loginBusy?'登录中…':'登录工作台'}} <span>→</span></button><p class="login-foot">仅限客服与管理员账号登录</p></form></main>
  <main v-else class="workspace">
    <aside class="sidebar"><div class="sidebar-title">工作空间 <span>WORKSPACE</span></div><nav aria-label="工作台导航"><button v-for="(value,index) in (['dashboard','pool','mine','all','knowledge','hotspots'] as Screen[])" :key="value" :class="{active:screen===value}" :aria-current="screen===value?'page':undefined" @click="navigate(value)"><span class="nav-index">{{String(index+1).padStart(2,'0')}}</span>{{labels[value]}}</button><template v-if="current?.role==='admin'"><div class="nav-group">系统管理</div><button :class="{active:screen==='users'}" @click="navigate('users')"><span class="nav-index">07</span>账号管理</button><button :class="{active:screen==='audit'}" @click="navigate('audit')"><span class="nav-index">08</span>操作记录</button></template></nav><div class="sidebar-bottom"><div class="rail-line"><i></i><i></i><i></i></div><p>每一段旅程<br>都值得被认真对待。</p><small>GAMECS / SERVICE DESK</small></div></aside>
    <section class="content"><div class="heading"><div><p class="eyebrow">GAMECS / 工作空间</p><h1>{{heading}}</h1><p class="subtitle">{{screen==='dashboard'?'汇总服务动态，了解玩家的声音。':screen==='knowledge'?'维护知识内容，让每一次回应更准确。':screen==='hotspots'?'查看玩家近期关注的问题。':screen==='users'?'管理账号角色和启用状态。':screen==='audit'?'查看工作台操作记录。':'查看工单并跟进处理进度。'}}</p></div><button v-if="screen==='knowledge'" class="primary" @click="edit()">＋ 新增知识</button></div>
      <div v-if="loading" class="empty" role="status">正在加载…</div><div v-else-if="loadError" class="empty" role="alert">加载失败，请检查网络后 <button class="outline" @click="refresh()">重试</button></div><div v-else-if="screen==='dashboard'" class="dashboard"><div class="metrics"><article v-for="metric in dashboardMetrics" :key="metric.label" class="metric"><div><span class="metric-icon">{{metric.icon}}</span><small>{{metric.label}}</small></div><strong>{{metric.value}}</strong><span>工单数量</span></article></div><div class="dashboard-grid"><div class="panel trend"><div class="panel-head"><h2>▥　近七日工单趋势</h2><small>每日新增</small></div><div v-if="trend.length" class="trend-chart"><div class="chart-grid"></div><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><polyline :points="trendPoints" fill="none" stroke="#91edd9" stroke-width="1" vector-effect="non-scaling-stroke"/><circle v-for="(point,i) in trend" :key="point.date" :cx="trend.length>1?i*100/(trend.length-1):50" :cy="95-point.count/trendMax*80" r="1.1" fill="#91edd9"/></svg><div class="chart-labels"><span v-for="point in trend" :key="point.date">{{point.date.slice(5)}}<small>{{point.count}} 条</small></span></div></div><p v-else class="empty">暂无趋势数据。</p></div><div class="panel"><div class="panel-head"><h2>▤　问题类型分布</h2><small>工单数</small></div><div v-for="item in categoryStats" :key="item.type" class="category"><div><span>{{({BUG:'故障',ADVICE:'建议',COMPLAINT:'投诉',CONSULT:'咨询'} as Record<string,string>)[item.type]||item.type}}</span><strong>{{item.count}}</strong></div><div class="category-track"><i :style="{width:item.count/categoryMax*100+'%'}"></i></div></div><p v-if="!categoryStats.length" class="empty">暂无分类数据。</p></div><div class="panel ranking"><div class="panel-head"><h2>♙　客服处理排行</h2><small>已完成</small></div><div v-for="(item,index) in handlers" :key="item.user_id" class="rank-row"><b>{{String(index+1).padStart(2,'0')}}</b><span>{{item.name}}</span><strong>{{item.count}} 条</strong></div><p v-if="!handlers.length" class="empty">暂无已完成工单。</p></div></div><div class="panel queue"><div class="panel-head"><h2>▤　待处理队列</h2><button class="link" @click="navigate('pool')">前往待接工单 →</button></div><div v-for="ticket in dashboardTickets.slice(0,5)" :key="ticket.id" class="queue-row"><small>{{ticket.ticket_no}}</small><strong>{{ticket.title}}</strong><span>{{statusLabel[ticket.status]||ticket.status}}</span><button class="link" @click="navigate('pool')">查看</button></div><p v-if="!dashboardTickets.length" class="empty">当前没有待接工单。</p></div></div>
      <div v-else-if="['pool','mine','all'].includes(screen)" class="ticket-workspace"><div class="ticket-board"><form class="ticket-search" @submit.prevent="offset=0;refresh()"><input v-model="ticketQuery" maxlength="200" aria-label="搜索工单" placeholder="工单编号或标题"><select v-model="ticketStatus" aria-label="工单状态"><option value="">全部状态</option><option v-for="(label,key) in statusLabel" :key="key" :value="key">{{label}}</option></select><button class="outline">筛选</button></form><div class="section-bar"><span>工单队列</span><small>共 {{ticketTotal}} 条</small></div><div class="ticket-list"><article v-for="ticket in tickets" :key="ticket.id" :class="['ticket-row',{chosen:selected?.id===ticket.id}]"><div class="ticket-number"><small>工单编号</small><b>{{ticket.ticket_no}}</b></div><div class="ticket-main"><h3>{{ticket.title}}</h3><p>{{ticket.content}}</p></div><div class="ticket-actions"><span class="status">{{statusLabel[ticket.status]||ticket.status}}</span><button class="ticket-select" @click="details(ticket)">查看详情 →</button></div></article><p v-if="!tickets.length" class="empty">当前没有工单。</p></div><div class="pager"><button class="outline" :disabled="offset===0" @click="page(-50)">上一页</button><span>第 {{Math.floor(offset/50)+1}} 页</span><button class="outline" :disabled="offset+50>=ticketTotal" @click="page(50)">下一页</button></div></div><div class="ticket-detail"><div class="detail-header"><strong>工单详情</strong><small>{{selected?.ticket_no||'TICKET DETAIL'}}</small></div><div v-if="selected" class="detail"><div class="detail-title"><h2>{{selected.title}}</h2><span class="status">{{statusLabel[selected.status]||selected.status}}</span></div><h3>玩家描述</h3><p class="detail-content">{{selected.content}}</p><div class="actions"><button v-if="screen==='pool'" class="primary" :disabled="pending[`assign-${selected.id}`]" @click="assign(selected.id)">接单 →</button><button v-if="selected.status==='ASSIGNED' && screen==='mine'" class="primary" :disabled="pending.transition" @click="transition(selected.id,'PROCESSING')">开始处理</button><label v-if="['ASSIGNED','PROCESSING'].includes(selected.status) && screen==='mine'">处理结果<textarea v-model="resolution" maxlength="500" rows="3" placeholder="说明处理结果"></textarea></label><button v-if="['ASSIGNED','PROCESSING'].includes(selected.status) && screen==='mine'" class="outline" :disabled="pending.transition" @click="transition(selected.id,'CLOSED')">完成工单</button></div><TicketThread :ticket-id="selected.id" :status="selected.status" :can-reply="current?.role==='admin' || current?.id===selected.handler_id" :events="selected.events"/><h3>✦　AI 分析</h3><p v-if="detailLoading">正在加载分析结果…</p><p v-else-if="analysisError">分析结果加载失败，请重新打开工单重试。</p><p v-else-if="analysis">{{analysis.status}} {{analysis.result?.suggest_reply || analysis.error || ''}}</p><p v-else>暂无分析结果</p><button v-if="!detailLoading && !analysisError && (!analysis || analysis.status==='failed')" class="outline" :disabled="pending.retry" @click="retry(selected.id)">开始分析</button><h3>▤　相似工单</h3><p v-for="item in similar" :key="item.id">{{item.title}}（{{item.score}}）</p><p v-if="detailLoading">正在加载相似工单…</p><p v-else-if="similarError">相似工单加载失败，请重新打开工单重试。</p><p v-else-if="!similar.length">暂无相似工单。</p></div><p v-else class="empty">选择工单查看详情。</p></div></div>
      <div v-else-if="screen==='knowledge'" class="knowledge-workspace"><div class="knowledge-list"><div class="section-bar"><span>知识库条目</span><small>共 {{knowledge.length}} 条</small></div><button v-for="item in knowledge" :key="item.id" class="knowledge-entry" :class="{chosen:selectedKnowledge?.id===item.id}" @click="selectedKnowledge=item"><small>#{{item.id}}</small><strong>{{item.title}}</strong><span>{{item.active?'已启用':'已停用'}}</span></button><p v-if="!knowledge.length" class="empty">暂无知识，点击右上角新增。</p></div><div class="ticket-detail"><div class="detail-header"><strong>知识详情</strong><small>KNOWLEDGE TICKET</small></div><div v-if="selectedKnowledge" class="detail"><small>游戏 {{selectedKnowledge.game_id}}　/　{{selectedKnowledge.active?'启用':'停用'}}</small><h2>{{selectedKnowledge.title}}</h2><p>索引状态：{{({pending:"待处理",processing:"处理中",completed:"已完成",failed:"失败",not_queued:"未排队"} as Record<string,string>)[selectedKnowledge.index_status] || selectedKnowledge.index_status}} <span v-if="selectedKnowledge.index_revision"> · 版本 {{selectedKnowledge.index_revision}}</span></p><p v-if="selectedKnowledge.index_error" role="alert">{{selectedKnowledge.index_error}}</p><h3>正文内容</h3><p class="detail-content">{{selectedKnowledge.content}}</p><div class="actions"><button class="primary" @click="edit(selectedKnowledge)">编辑知识</button><button class="outline" :disabled="pending[`index-${selectedKnowledge.id}`]" @click="indexKnowledge(selectedKnowledge.id)">重建索引</button></div></div><p v-else class="empty">选择条目查看详情。</p></div></div>
      <div v-else-if="screen==='hotspots'" class="list"><div v-for="hot in hotspots" :key="hot.rank" class="row hot-row"><b class="rank-number">{{String(hot.rank).padStart(2,'0')}}</b><strong>{{hot.keyword}}</strong><span>{{hot.count}} 条</span><small>{{hot.stat_date}}　/　{{hot.source_type==='fallback'?'历史数据':'当日统计'}}</small></div><p v-if="!hotspots.length" class="empty">暂无热点数据。</p></div>
      <div v-else-if="screen==='audit'" class="audit-workspace"><div class="audit-list list"><div class="row"><strong>{{legacyAudit?'旧系统记录':'新系统记录'}}</strong><button class="outline" @click="legacyAudit=!legacyAudit;selectedAudit=null;offset=0;refresh()">{{legacyAudit?'查看新系统记录':'查看旧系统记录'}}</button></div><template v-if="legacyAudit"><button v-for="(entry,index) in oldAudit" :key="index" class="audit-row" @click="selectedAudit={title:String(entry.record.module||entry.record.title||entry.source)+' · '+String(entry.record.action||entry.record.business_type||'操作'),actor:String(entry.record.operator_id??entry.record.oper_name??'未知'),time:formatDate(entry.record.create_time||entry.record.oper_time),target:entry.source}"><span>{{formatDate(entry.record.create_time||entry.record.oper_time)}}</span><strong>{{entry.record.module||entry.record.title||entry.source}} · {{entry.record.action||entry.record.business_type||'操作'}}</strong><small>{{entry.record.operator_id??entry.record.oper_name??'未知'}}</small></button><p v-if="!oldAudit.length" class="empty">暂无旧系统记录。</p></template><template v-else><button v-for="entry in audit" :key="entry.id" class="audit-row" @click="selectedAudit={title:entry.action,actor:String(entry.actor_id),time:formatDate(entry.created_at),target:entry.target_type+' #'+entry.target_id}"><span>{{formatDate(entry.created_at)}}</span><strong>{{entry.action}}</strong><small>操作人 {{entry.actor_id}}　/　{{entry.target_type}} #{{entry.target_id}}</small></button><p v-if="!audit.length" class="empty">暂无新系统操作记录。</p></template><div class="pager"><button class="outline" :disabled="offset===0" @click="selectedAudit=null;page(-50)">上一页</button><span>第 {{Math.floor(offset/50)+1}} 页</span><button class="outline" :disabled="(legacyAudit?oldAudit.length:audit.length)<50" @click="selectedAudit=null;page(50)">下一页</button></div></div><div class="ticket-detail"><div class="detail-header"><strong>操作详情</strong><small>ACTIVITY LOG</small></div><div v-if="selectedAudit" class="detail"><h2>{{selectedAudit.title}}</h2><h3>记录信息</h3><div class="audit-fields"><p><span>操作时间</span>{{selectedAudit.time}}</p><p><span>操作人</span>{{selectedAudit.actor}}</p><p><span>操作对象</span>{{selectedAudit.target}}</p></div></div><p v-else class="empty">选择一条记录查看详情。</p></div></div>
      <div v-else class="list users-list"><form class="row search" @submit.prevent="offset=0;refresh()"><label class="sr-only" for="user-query">按用户名搜索</label><input id="user-query" v-model="userQuery" placeholder="按用户名搜索"><button class="outline">搜索</button></form><div class="users-head"><span>用户名</span><span>显示名称</span><span>角色</span><span>状态</span><span>操作</span></div><div v-for="user in users" :key="user.id" class="user-row"><strong>{{user.username}}</strong><span>{{user.display_name}}</span><label class="sr-only" :for="`role-${user.id}`">{{user.username}} 的角色</label><select :id="`role-${user.id}`" v-model="user.role"><option value="player">玩家</option><option value="staff">客服</option><option value="admin">管理员</option></select><label class="check"><input v-model="user.active" type="checkbox"> {{user.active?'已启用':'已停用'}}</label><button class="primary" :disabled="pending[`user-${user.id}`]" @click="updateUser(user)">保存</button></div><p v-if="!users.length" class="empty">没有找到账号。</p><div class="pager"><button class="outline" :disabled="offset===0" @click="page(-50)">上一页</button><span>第 {{Math.floor(offset/50)+1}} 页</span><button class="outline" :disabled="users.length<50" @click="page(50)">下一页</button></div></div>
    </section>
  </main>
  <el-dialog v-model="editor" :title="editing?'编辑知识':'新增知识'" width="min(680px, 92vw)"><form class="editor" @submit.prevent="saveKnowledge"><label>游戏 ID<input v-model.number="form.game_id" type="number" min="1" required></label><label>标题<input v-model="form.title" maxlength="200" required></label><label>内容<textarea v-model="form.content" rows="6" required></textarea></label><label class="check"><input v-model="form.active" type="checkbox"> 启用</label><button class="primary" :disabled="pending.saveKnowledge">{{pending.saveKnowledge?'保存中…':'保存知识'}}</button></form></el-dialog>
</div>
</template>
